import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
// Core's UploadImageButton reloads the page on success and addresses one fixed
// route. Only its markup is reused here.
export default class UploadPollImageButton extends Component {
  loading = false;
  uploadedImageUrl = false;
  fileName = (() => undefined)();
  view(vnode) {
    const {
      name,
      poll,
      option,
      onUpload,
      className,
      ...attrs
    } = this.attrs;
    const imageUrl = this.getImageUrl();
    const buttonAttrs = {
      ...attrs,
      className: classList('Button', className),
      loading: this.loading
    };
    return m("div", {
      className: "UploadImageButton"
    }, imageUrl && m("div", {
      className: "UploadImageButton-image"
    }, m("img", {
      src: imageUrl,
      alt: this.imageAlt()
    })), m(Button, Object.assign({}, buttonAttrs, {
      onclick: imageUrl ? this.remove.bind(this) : this.upload.bind(this)
    }), app.translator.trans(`fof-polls.forum.upload_image.${imageUrl ? 'remove' : 'upload'}_button`)));
  }
  imageAlt() {
    return this.attrs.poll?.imageAlt() || this.attrs.option?.answer() || '';
  }
  upload() {
    if (this.loading) return;
    this.$input = $('<input type="file">');
    this.$input.appendTo('body').hide().trigger('click').on('change', e => {
      const body = new FormData();
      body.append(this.attrs.name, $(e.target)[0].files[0]);
      this.loading = true;
      m.redraw();
      app.request({
        method: 'POST',
        url: this.resourceUrl(),
        serialize: raw => raw,
        body
      }).then(this.success.bind(this), this.failure.bind(this));
    });
  }
  remove() {
    this.loading = true;
    m.redraw();

    // Before the poll exists there is no id, so the file name addresses it.
    const fileName = !this.attrs.poll?.exists && !this.attrs.option?.exists ? this.fileName : undefined;
    app.request({
      method: 'DELETE',
      url: this.resourceUrl(fileName)
    }).then(upload => {
      this.attrs.poll?.exists && this.attrs.poll.pushAttributes({
        image: null,
        imageUrl: null,
        isImageUpload: false
      });
      this.attrs.option?.exists && this.attrs.option.pushAttributes({
        imageUrl: false
      });
      return upload;
    }).then(this.success.bind(this), this.failure.bind(this));
  }
  resourceUrl(fileName) {
    if (fileName === void 0) {
      fileName = undefined;
    }
    let url = `${app.forum.attribute('apiUrl')}/polls/${this.attrs.name}`;
    if (fileName) return `${url}/name/${fileName}`;
    if (this.attrs.poll?.exists) url += `/${this.attrs.poll.id()}`;
    if (this.attrs.option?.exists) url += `/${this.attrs.option.id()}`;
    return url;
  }
  getImageUrl() {
    if (this.uploadedImageUrl !== false) return this.uploadedImageUrl;
    return this.attrs.poll?.imageUrl() || this.attrs.option?.imageUrl();
  }
  success(response) {
    this.loading = false;
    this.uploadedImageUrl = response?.fileUrl;
    this.fileName = response?.fileName;
    if (response?.fileName) {
      this.attrs.poll?.exists && this.attrs.poll.pushAttributes({
        image: response.fileName,
        imageUrl: response.fileUrl,
        isImageUpload: true
      });
      this.attrs.option?.exists && this.attrs.option.pushAttributes({
        imageUrl: response.fileUrl,
        image_url: response.fileName,
        isImageUpload: true
      });
    }
    this.attrs.onUpload?.(response?.fileName);
    m.redraw();
    this.$input?.remove();
  }
  failure() {
    this.loading = false;
    m.redraw();
    this.$input?.remove();
  }
}
flarum.reg.add('fof-polls', 'forum/components/UploadPollImageButton', UploadPollImageButton);